49	import org.springframework.samples.petclinic.util.Households;
50	import org.springframework.samples.petclinic.util.Localities;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.context.request.RequestAttributes;
56	import org.springframework.web.context.request.RequestContextHolder;
57	import org.springframework.web.context.request.ServletRequestAttributes;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
73	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
74	     * numeric {@code membershipLevel}.
75	     */
76	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
77	
78	    /**
79	     * Name of the optional request header carrying an idempotency token for owner creation.
80	     */
81	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
82	
83	    /**
84	     * Idempotency store mapping a previously seen {@code Idempotency-Key} to the id of the owner
85	     * originally created under it. When a create repeats with a key already present here, the
86	     * originally created owner is returned (200 OK) instead of creating a duplicate.
87	     */
88	    private final java.util.Map<String, Integer> idempotencyKeyToOwnerId =
89	        new java.util.concurrent.ConcurrentHashMap<>();
90	
91	    private final ClinicService clinicService;
92	
93	    private final OwnerMapper ownerMapper;
94	
95	    private final PetMapper petMapper;
96	
97	    private final VisitMapper visitMapper;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
112	        Collection<Owner> owners;
113	        if (lastName != null) {
114	            owners = this.clinicService.findOwnerByLastName(lastName);
115	        } else {
116	            owners = this.clinicService.findAllOwners();
117	        }
118	        if (owners.isEmpty()) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
127	        Owner owner = this.clinicService.findOwnerById(ownerId);
128	        if (owner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        String idempotencyKey = currentIdempotencyKey();
138	        if (idempotencyKey != null) {
139	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
140	            if (existingId != null) {
141	                Owner existing = this.clinicService.findOwnerById(existingId);
142	                if (existing != null) {
143	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
144	                }
145	            }
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        applyAddress(owner, ownerFieldsDto);
150	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
151	        rejectFutureRegistrationDate(registrationDate);
152	        if (registrationDate == null) {
153	            registrationDate = java.time.LocalDate.now();
154	        }
155	        registrationDate = toBusinessDay(registrationDate);
156	        owner.setRegistrationDate(registrationDate);
157	        rejectDailyLimitReached(registrationDate);
158	        rejectCityAtCapacity(owner.getCity());
159	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
160	        owner.setTelephone(telephone);
161	        String email = normalizeEmail(ownerFieldsDto.getEmail());
162	        owner.setEmail(email);
163	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
164	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
165	        rejectDuplicateIdentity(owner);
166	        rejectDuplicateHousehold(owner, sharesHousehold);
167	        String region = Localities.region(owner.getPostcode(), owner.getCity());
168	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
169	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
170	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
171	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
172	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
173	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
174	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
175	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
176	        this.clinicService.saveOwner(owner);
177	        if (idempotencyKey != null) {
178	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
179	        }
180	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
181	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
182	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
183	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
184	        headers.setLocation(UriComponentsBuilder.newInstance()
185	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
186	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    /**
190	     * Reads the optional {@code Idempotency-Key} header from the current request, if any. A create
191	     * carrying this header is idempotent: the first create under a key is recorded, and a later create
192	     * with the same key returns the originally created owner instead of creating a duplicate.
193	     *
194	     * @return the trimmed idempotency key, or {@code null} when the header is absent, blank or there is
195	     *         no active servlet request
196	     */
197	    private String currentIdempotencyKey() {
198	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
199	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
200	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
201	            if (key != null && !key.isBlank()) {
202	                return key.trim();
203	            }
204	        }
205	        return null;
206	    }
207	
208	    /**
209	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
210	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
211	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
212	     * date, before any business-day adjustment.
213	     *
214	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
215	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
216	     */
217	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
218	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
219	            throw new FutureRegistrationDateException(registrationDate);
220	        }
221	    }
222	
223	    /**
224	     * The maximum number of owners that may be created in a single day. Creating an owner once this
225	     * many owners already carry today's {@code registrationDate} is rejected.
226	     */
227	    private static final int DAILY_OWNER_LIMIT = 100;
228	
229	    /**
230	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
231	     * given business day as their {@code registrationDate}. The count is keyed by the
232	     * business-day-adjusted registration date of the owner being created (see
233	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
234	     * with no {@code registrationDate} are ignored.
235	     *
236	     * @param registrationDate the business-day-adjusted registration date of the owner being created
237	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
238	     */
239	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
240	        long count = this.clinicService.findAllOwners().stream()
241	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
242	            .count();
243	        if (count >= DAILY_OWNER_LIMIT) {
244	            throw new DailyOwnerLimitException(registrationDate);
245	        }
246	    }
247	
248	    /**
249	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
250	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
251	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
252	     */
253	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
254	
255	    /**
256	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
257	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
258	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
259	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
260	     * owner being created is excluded (it has not yet been saved).
261	     *
262	     * @param registrationDate the business-day-adjusted registration date of the owner being created
263	     * @return {@code true} if more than the threshold of owners already carry this business day
264	     */
265	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
266	        long count = this.clinicService.findAllOwners().stream()
267	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
268	            .count();
269	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
270	    }
271	
272	    /**
273	     * The fixed public holidays the business-day roll skips. A registration date landing on any of
274	     * these dates is rolled forward, just as it is for a weekend.
275	     */
276	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
277	        java.time.LocalDate.parse("2026-01-01"),
278	        java.time.LocalDate.parse("2026-01-26"),
279	        java.time.LocalDate.parse("2026-04-25"),
280	        java.time.LocalDate.parse("2026-12-25"),
281	        java.time.LocalDate.parse("2026-12-28"));
282	
283	    /**
284	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
285	     * holiday is moved forward to the next non-holiday weekday; an ordinary weekday is returned
286	     * unchanged. This applies to the effective registration date whether it was supplied in the
287	     * request or defaulted to the server date, and every value derived from the registration date
288	     * uses the adjusted result.
289	     *
290	     * @param date the effective registration date
291	     * @return {@code date} itself when it is a non-holiday weekday, otherwise the next business day
292	     */
293	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
294	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
295	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
296	            || PUBLIC_HOLIDAYS.contains(date)) {
297	            date = date.plusDays(1);
298	        }
299	        return date;
300	    }
301	
302	    /**
303	     * The maximum number of owners a single city may contain. Creating an owner in a city that
304	     * already holds this many owners is rejected.
305	     */
306	    private static final int CITY_CAPACITY = 50;
307	
308	    /**
309	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
310	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
311	     * treated as empty).
312	     *
313	     * @param city the city of the owner being created
314	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
315	     */
316	    private void rejectCityAtCapacity(String city) {
317	        String cityValue = city == null ? "" : city;
318	        long count = this.clinicService.findAllOwners().stream()
319	            .filter(existing -> cityValue.equalsIgnoreCase(
320	                existing.getCity() == null ? "" : existing.getCity()))
321	            .count();
322	        if (count >= CITY_CAPACITY) {
323	            throw new CityAtCapacityException(city);
324	        }
325	    }
326	
327	    /**
328	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
329	     * REGION is the owner's canonical region (derived by preferring the postcode, see
330	     * {@link Localities#region(String, String)} — the same region derivation shared with the
331	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
332	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
333	     * The code is derived from the owner's own identity fields; it carries no sequence number.
334	     * <p>
335	     * When the computed code collides with an existing owner's {@code customerCode}, it is
336	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
337	     * it unique (e.g. {@code 'NSW-3A7F9C2E-2'}), and the de-duplicated code is returned.
338	     *
339	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
340	     * @param telephone the owner's normalized (E.164) telephone
341	     * @param lastName the owner's last name
342	     * @return the assigned customer code, de-duplicated to be unique among existing owners
343	     */
344	    private String assignCustomerCode(String region, String telephone, String lastName) {
345	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
346	        String hash8 = sha256UpperHex(basis).substring(0, 8);
347	        String code = region + "-" + hash8;
348	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
349	            .map(Owner::getCustomerCode)
350	            .filter(java.util.Objects::nonNull)
351	            .collect(java.util.stream.Collectors.toSet());
352	        if (!existing.contains(code)) {
353	            return code;
354	        }
355	        for (int n = 2; ; n++) {
356	            String candidate = code + "-" + n;
357	            if (!existing.contains(candidate)) {
358	                return candidate;
359	            }
360	        }
361	    }
362	
363	    /**
364	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
365	     */
366	    private static String sha256UpperHex(String value) {
367	        try {
368	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
369	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
370	            StringBuilder sb = new StringBuilder(digest.length * 2);
371	            for (byte b : digest) {
372	                sb.append(String.format("%02X", b));
373	            }
374	            return sb.toString();
375	        }
376	        catch (java.security.NoSuchAlgorithmException e) {
377	            throw new IllegalStateException("SHA-256 not available", e);
378	        }
379	    }
380	
381	    /**
382	     * Counts how many existing owners share the given first and last name, compared
383	     * case-insensitively, at the time this owner is created. The value excludes the owner
384	     * being created (which has not yet been saved) and is stored on the new owner and returned
385	     * as its {@code namesakeCount}.
386	     *
387	     * @param firstName the first name of the owner being created
388	     * @param lastName the last name of the owner being created
389	     * @return the number of existing owners with the same first and last name
390	     */
391	    private int countNamesakes(String firstName, String lastName) {
392	        String first = firstName == null ? "" : firstName;
393	        String last = lastName == null ? "" : lastName;
394	        return (int) this.clinicService.findAllOwners().stream()
395	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
396	                && last.equalsIgnoreCase(existing.getLastName()))
397	            .count();
398	    }
399	
400	    /**
401	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
402	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
403	     * name and postcode). The value excludes the owner being created (which has not yet been saved), so
404	     * the household's size after this create is this count plus one. It is stored on the new owner.
405	     *
406	     * @param lastName the last name of the owner being created
407	     * @param postcode the postcode of the owner being created
408	     * @return the number of existing owners sharing this owner's household
409	     */
410	    private int countHouseholdMembers(String lastName, String postcode) {
411	        String householdId = Households.householdId(lastName, postcode);
412	        return (int) this.clinicService.findAllOwners().stream()
413	            .filter(existing -> householdId.equals(
414	                Households.householdId(existing.getLastName(), existing.getPostcode())))
415	            .count();
416	    }
417	
418	    /**
419	     * Rejects creating an owner that would join an existing household without opting in. The household
420	     * is keyed on the computed {@code householdId} (see {@link Households#householdId}, derived from the
421	     * normalized last name and postcode), so an owner sharing an existing owner's last name and postcode
422	     * is the same household. When another owner already belongs to that household the create is rejected,
423	     * unless the request opts in with {@code sharesHousehold}, which bypasses this block and creates the
424	     * owner as a declared household member. An owner with no postcode is never treated as a household
425	     * duplicate.
426	     *
427	     * @param owner the owner being created, with its last name and postcode already set
428	     * @param sharesHousehold whether the request opted in via {@code sharesHousehold}
429	     * @throws DuplicateHouseholdException (409 Conflict) if the owner joins an existing household and did
430	     *         not opt in
431	     */
432	    private void rejectDuplicateHousehold(Owner owner, boolean sharesHousehold) {
433	        if (sharesHousehold) {
434	            return;
435	        }
436	        String postcode = owner.getPostcode();
437	        if (postcode == null) {
438	            return;
439	        }
440	        String householdId = Households.householdId(owner.getLastName(), postcode);
441	        boolean exists = this.clinicService.findAllOwners().stream()
442	            .filter(this::isNotDeleted)
443	            .anyMatch(existing -> householdId.equals(
444	                Households.householdId(existing.getLastName(), existing.getPostcode())));
445	        if (exists) {
446	            throw new DuplicateHouseholdException(owner.getLastName(), postcode);
447	        }
448	    }
449	
450	    /**
451	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
452	     * sharing this owner's last name (compared case-insensitively) and postcode (an exact match of the
453	     * stored 4-digit value) while carrying a <em>different</em> telephone. A soft match is distinct from
454	     * the hard duplicate rejected earlier by {@link #rejectDuplicateIdentity}: the owner is still
455	     * created, but flagged. When more than one existing owner matches, the earliest (lowest id) is
456	     * returned so the reference is deterministic. An owner with no postcode can never soft-match.
457	     *
458	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
459	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
460	     */
461	    private Integer findPossibleDuplicateOf(Owner owner) {
462	        String postcode = owner.getPostcode();
463	        if (postcode == null) {
464	            return null;
465	        }
466	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
467	        String telephone = owner.getTelephone();
468	        return this.clinicService.findAllOwners().stream()
469	            .filter(this::isNotDeleted)
470	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
471	            .filter(existing -> postcode.equals(existing.getPostcode()))
472	            .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
473	            .map(Owner::getId)
474	            .filter(java.util.Objects::nonNull)
475	            .min(java.util.Comparator.naturalOrder())
476	            .orElse(null);
477	    }
478	
479	    /**
480	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
481	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
482	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
483	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
484	     * {@code "+61412345678"}. The E.164 value is stored and returned.
485	     * <p>
486	     * The national-number length (the digits after the country code) is additionally validated for
487	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
488	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
489	     *
490	     * @param telephone the raw telephone as submitted
491	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
492	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
493	     *         or its national-number length is wrong for its country code
494	     */
495	    private String normalizeTelephone(String telephone) {
496	        String raw = telephone == null ? "" : telephone.trim();
497	        boolean hasCountryCode = raw.startsWith("+");
498	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
499	        if (hasCountryCode) {
500	            cleaned = cleaned.substring(1);
501	        }
502	        String digits;
503	        if (hasCountryCode) {
504	            digits = cleaned;
505	        } else {
506	            if (cleaned.startsWith("0")) {
507	                cleaned = cleaned.substring(1);
508	            }
509	            digits = "61" + cleaned;
510	        }
511	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
512	            throw new InvalidTelephoneException(telephone);
513	        }
514	        return "+" + digits;
515	    }
516	
517	    /**
518	     * Checks the national-number length of an E.164 digit string against its country code for the
519	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
520	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
521	     *
522	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
523	     * @return {@code true} if the national-number length is acceptable for the country code
524	     */
525	    private boolean hasValidNationalLength(String digits) {
526	        if (digits.startsWith("61")) {
527	            return digits.length() - 2 == 9;
528	        }
529	        if (digits.startsWith("1")) {
530	            return digits.length() - 1 == 10;
531	        }
532	        return true;
533	    }
534	
535	    /**
536	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
537	     * multi-character top-level label. Deliberately lenient about the exact character set while still
538	     * rejecting values that are clearly not addresses (e.g. missing '@').
539	     */
540	    private static final java.util.regex.Pattern EMAIL_PATTERN =
541	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
542	
543	    /**
544	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
545	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
546	     * lower-cased email domain.
547	     */
548	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
549	        "mailinator.com", "tempmail.com", "guerrillamail.com");
550	
551	    /**
552	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
553	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
554	     * lower-cased before being stored and returned.
555	     *
556	     * @param email the raw email as submitted, may be {@code null}
557	     * @return the lower-cased email, or {@code null} when none was supplied
558	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
559	     */
560	    private String normalizeEmail(String email) {
561	        if (email == null || email.isBlank()) {
562	            return null;
563	        }
564	        String trimmed = email.trim();
565	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
566	            throw new InvalidEmailException(email);
567	        }
568	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
569	        String domain = normalized.substring(normalized.indexOf('@') + 1);
570	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
571	            throw new DisposableEmailException(email);
572	        }
573	        return normalized;
574	    }
575	
576	    /**
577	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
578	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
579	     * {@link Localities#region}) accepts any 4-digit postcode.
580	     */
581	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
582	        "NSW", new int[] {2000, 2099},
583	        "VIC", new int[] {3000, 3099},
584	        "QLD", new int[] {4000, 4099});
585	
586	    /**
587	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
588	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
589	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
590	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
591	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
592	     *
593	     * @param city the owner's city, used to derive the region whose range constrains the postcode
594	     * @param postcode the raw postcode as submitted, may be {@code null}
595	     * @return the postcode when supplied, or {@code null} when none was supplied
596	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
597	     *         out of range for the city's region
598	     */
599	    private String validatePostcode(String city, String postcode) {
600	        if (postcode == null || postcode.isBlank()) {
601	            return null;
602	        }
603	        if (!postcode.matches("[0-9]{4}")) {
604	            throw new InvalidPostcodeException(postcode);
605	        }
606	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
607	        if (range != null) {
608	            int value = Integer.parseInt(postcode);
609	            if (value < range[0] || value > range[1]) {
610	                throw new InvalidPostcodeException(postcode);
611	            }
612	        }
613	        return postcode;
614	    }
615	
616	    /**
617	     * Common street-type abbreviations expanded to their full word during address normalization.
618	     */
619	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
620	        "ST", "STREET",
621	        "RD", "ROAD",
622	        "AVE", "AVENUE");
623	
624	    /**
625	     * Applies the owner's address on create from the structured fields when present, falling back to the
626	     * flat {@code address} for backward compatibility. An owner must supply an address in at least one
627	     * form: a non-blank {@code addressLine1} (the structured form, preferred) or a non-blank flat
628	     * {@code address}; when neither is present the create is rejected.
629	     * <p>
630	     * Whichever address fields are supplied are normalized (see {@link #normalizeAddress}). When the
631	     * structured form is used the normalized {@code addressLine1} and, when supplied, {@code addressLine2}
632	     * are stored on the owner and the composed {@code address} is the normalized {@code addressLine1} with
633	     * a single space and the normalized {@code addressLine2} appended when {@code addressLine2} is present.
634	     * When only the flat form is used the normalized flat value becomes the stored {@code address} and the
635	     * structured lines are left unset. The stored {@code address} is the value every later step reads.
636	     *
637	     * @param owner the owner being created
638	     * @param ownerFieldsDto the submitted owner fields carrying the raw address input
639	     * @throws InvalidAddressException (400 Bad Request) if no address is supplied in either form
640	     */
641	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
642	        String rawLine1 = ownerFieldsDto.getAddressLine1();
643	        String rawLine2 = ownerFieldsDto.getAddressLine2();
644	        String rawFlat = ownerFieldsDto.getAddress();
645	        boolean hasLine1 = rawLine1 != null && !rawLine1.isBlank();
646	        boolean hasFlat = rawFlat != null && !rawFlat.isBlank();
647	        if (!hasLine1 && !hasFlat) {
648	            throw new InvalidAddressException(rawLine1 != null ? rawLine1 : rawFlat);
649	        }
650	        if (hasLine1) {
651	            String line1 = normalizeAddress(rawLine1);
652	            String line2 = (rawLine2 != null && !rawLine2.isBlank()) ? normalizeAddress(rawLine2) : null;
653	            owner.setAddressLine1(line1);
654	            owner.setAddressLine2(line2);
655	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
656	        } else {
657	            owner.setAddressLine1(null);
658	            owner.setAddressLine2(null);
659	            owner.setAddress(normalizeAddress(rawFlat));
660	        }
661	    }
662	
663	    /**
664	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
665	     * whitespace collapse to a single space, the value is upper-cased and common street-type
666	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
667	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
668	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
669	     * for every address comparison (household duplicate detection and the shared household id).
670	     *
671	     * @param address the raw address as submitted
672	     * @return the normalized address
673	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
674	     */
675	    private String normalizeAddress(String address) {
676	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
677	        if (collapsed.isEmpty()) {
678	            throw new InvalidAddressException(address);
679	        }
680	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
681	        StringBuilder normalized = new StringBuilder(collapsed.length());
682	        for (int i = 0; i < tokens.length; i++) {
683	            if (i > 0) {
684	                normalized.append(' ');
685	            }
686	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
687	        }
688	        return normalized.toString();
689	    }
690	
691	    /**
692	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
693	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
694	     * owners are duplicates when they share the same normalized telephone and the same normalized email
695	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
696	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
697	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
698	     * still match.
699	     * <p>
700	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
701	     * grouping, so two members of the same household with different telephones have different
702	     * identities and are both allowed. Only owners with the same telephone and email collide.
703	     *
704	     * @param owner the owner being created, with its telephone and email already normalized
705	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
706	     */
707	    private void rejectDuplicateIdentity(Owner owner) {
708	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
709	        boolean duplicate = this.clinicService.findAllOwners().stream()
710	            .filter(this::isNotDeleted)
711	            .anyMatch(existing -> identity.equals(
712	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
713	        if (duplicate) {
714	            String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
715	            throw new DuplicateIdentityException(
716	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
717	        }
718	    }
719	
720	    /**
721	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
722	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
723	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
724	     */
725	    /**
726	     * Whether an existing owner is not soft-deleted. A soft-deleted owner (its {@code deleted} flag
727	     * set) is retained but ignored by the create endpoint's duplicate and identity checks, so a
728	     * normally-blocking duplicate is allowed when the only matching owner has been deleted.
729	     */
730	    private boolean isNotDeleted(Owner owner) {
731	        return !Boolean.TRUE.equals(owner.getDeleted());
732	    }
733	
734	    private String personalIdentity(String telephone, String email) {
735	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
736	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
737	    }
738	
739	    /**
740	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
741	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
742	     * when its national-number length does not match its country code.
743	     */
744	    private String toE164OrNull(String telephone) {
745	        try {
746	            return normalizeTelephone(telephone);
747	        } catch (InvalidTelephoneException e) {
748	            return null;
749	        }
750	    }
